def gen(rng):
    def fmt(a, b):
        return f'{len(a)} {len(b)}\n' + ' '.join(map(str, a)) + '\n' + ' '.join(map(str, b))
    def arr(n, lo, hi):
        return sorted(rng.randint(lo, hi) for _ in range(n))
    tests = [fmt([], [5]), fmt([5], []), fmt([1], [1]), fmt([1, 2], [3, 4]), fmt([3, 4], [1, 2]),
             fmt([2, 2, 2], [2, 2]), fmt([-1000000], [1000000]), fmt([], [1, 2, 3, 4])]
    for _ in range(8):
        tests.append(fmt(arr(rng.randint(0, 12), -20, 20), arr(rng.randint(1, 12), -20, 20)))
    M = 40000
    tests.append(fmt(arr(M, -1000000, 1000000), arr(M, -1000000, 1000000)))
    tests.append(fmt(arr(M, -1000000, -1), arr(M, 0, 1000000)))
    tests.append(fmt(arr(M, 0, 1000000), arr(1, -1000000, 1000000)))
    tests.append(fmt([], arr(M, -1000000, 1000000)))
    tests.append(fmt(arr(M - 1, -50, 50), arr(M, -50, 50)))
    return tests
